"use strict";

const { spawnSync } = require("node:child_process");
const { existsSync, readFileSync } = require("node:fs");
const { join, resolve } = require("node:path");

const root = resolve(__dirname, "..");
const errors = [];
const notes = [];
const goalProgress = Object.freeze({
  substratePct: 93,
  substrateFloorPct: 65,
  frontendPct: 100,
  frontendFloorPct: 60,
});

function read(relativePath) {
  return readFileSync(join(root, relativePath), "utf8");
}

function requireIncludes(source, relativePath, label, needles) {
  for (const needle of needles) {
    if (!source.includes(needle)) {
      errors.push(`${relativePath} must keep ${label}: ${needle}`);
    }
  }
}

function forbidIncludes(source, relativePath, label, needles) {
  for (const needle of needles) {
    if (source.includes(needle)) {
      errors.push(`${relativePath} must avoid ${label}: ${needle}`);
    }
  }
}

function requireOrdered(source, relativePath, label, needles) {
  let cursor = -1;
  for (const needle of needles) {
    const index = source.indexOf(needle);
    if (index === -1) {
      errors.push(`${relativePath} must keep ${label}: ${needle}`);
      continue;
    }
    if (index < cursor) {
      errors.push(`${relativePath} must keep ${label} in order: ${needles.join(" -> ")}`);
      return;
    }
    cursor = index;
  }
}

function requirePercentAtLeast(line, relativePath, label, metric, floor) {
  const escapedMetric = metric.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  const match = line.match(new RegExp(`${escapedMetric}=[^;]*?([0-9]+(?:\\.[0-9]+)?)%`));
  if (!match) {
    errors.push(`${relativePath} must keep ${label}: missing ${metric} percentage`);
    return;
  }
  const value = Number(match[1]);
  if (!Number.isFinite(value) || value < floor) {
    errors.push(`${relativePath} must keep ${label}: ${metric} ${value}% below ${floor}%`);
  }
}

function requirePattern(source, relativePath, label, pattern) {
  if (!pattern.test(source)) {
    errors.push(`${relativePath} must keep ${label}: ${pattern}`);
  }
}

function requireConstArrayCount(source, relativePath, constName, expectedCount) {
  const match = source.match(new RegExp(`const ${constName} = \\[([\\s\\S]*?)\\n\\s*\\];`));
  if (!match) {
    errors.push(`${relativePath} must keep const ${constName} array`);
    return "";
  }
  const count = [...match[1].matchAll(/"[^"]+"/g)].length;
  if (count !== expectedCount) {
    errors.push(`${relativePath} const ${constName} must keep ${expectedCount} entries, found ${count}`);
  }
  return match[1];
}

function requireArrayPatternCount(source, relativePath, label, pattern, expectedCount) {
  const match = source.match(pattern);
  if (!match) {
    errors.push(`${relativePath} must keep ${label}`);
    return "";
  }
  const count = [...match[1].matchAll(/"[^"]+"/g)].length;
  if (count !== expectedCount) {
    errors.push(`${relativePath} ${label} must keep ${expectedCount} entries, found ${count}`);
  }
  return match[1];
}

function commandLine(command, args) {
  return [command, ...args].join(" ");
}

function spawnOutput(result) {
  const output = `${result.stdout ?? ""}${result.stderr ?? ""}`.trim();
  return output.length === 0 ? "<no output>" : output;
}

function spawnFailure(label, command, args, result) {
  const status = result.status === null || result.status === undefined ? "null" : String(result.status);
  const signal = result.signal ? ` signal=${result.signal}` : "";
  const error = result.error ? ` error=${result.error.message}` : "";
  return `${label} failed: ${commandLine(command, args)} status=${status}${signal}${error}\n${spawnOutput(result)}`;
}

function runScorecardCheck(label, fn) {
  process.stderr.write(`[scorecard] start ${label}\n`);
  const beforeErrorCount = errors.length;
  try {
    fn();
  } catch (err) {
    errors.push(`${label} threw: ${err && err.stack ? err.stack : String(err)}`);
  }
  const status = errors.length === beforeErrorCount ? "done" : "issues";
  process.stderr.write(`[scorecard] ${status} ${label}\n`);
}

