function checkSubstrateEvidence() {
  requireIncludes(read("src/backend/program.zig"), "src/backend/program.zig", "dense FFN unary projection-pair command formation", [
    "denseProjectionPairSingleElementwiseChainCompatible",
    "matmulElementwiseSidecarCompatible(gate, first)",
    "if (first.op.isBinary()) return false",
    "test \"program command stream fuses dense paired projection unary activation product chain\"",
  ]);
  requireIncludes(read("src/backend/metal.zig"), "src/backend/metal.zig", "Metal unary projection sidecar lowering", [
    "float matmul_elementwise_unary(uint op, float v)",
    "case 40: return v / (1.0f + exp(-v));",
    "else ew = matmul_elementwise_unary(p.ew_op, val);",
    "denseProjectionPairSingleElementwiseChainCompatible(gate, first, up, product)",
  ]);
  requireIncludes(read("benchmarks/llama_smollm_bench.zig"), "benchmarks/llama_smollm_bench.zig", "projection chain local-op debug microscope", [
    "local_base={d} local_ops={s},{s},{s},{s},{s},{s},{s},{s}",
    "projection_debug.local_op_base",
    "projection_debug.local_op_tags[7]",
  ]);

  const args = ["scripts/bench_status.cjs", "--trend-gate", "--substrate-gate"];
  const result = spawnSync(process.execPath, args, {
    cwd: root,
    encoding: "utf8",
    stdio: ["ignore", "pipe", "pipe"],
  });
  const output = `${result.stdout ?? ""}${result.stderr ?? ""}`;
  if (result.status !== 0) {
    errors.push(spawnFailure("bench substrate gate", process.execPath, args, result));
    return;
  }
  requireIncludes(output, "bench substrate gate output", "no-fallback substrate proof", [
    "bench substrate gate: pass",
    "fallback=0",
    "dispatch=212",
    "dispatch=242",
    "commands=211",
    "commands=212",
    "commands=242",
    "ggml=",
    "ggml_floor=",
    "to90=",
    "ref=",
    "frontier weakest=q8_0/prompt",
    "sidecars=",
    "q8_decode_sidecars=qmatvec_elementwise:60",
    "pass offline-stencil",
    "patch_holes=450",
    "shape pp=211/1654 saved=1443 tg=181/1654 saved=1473",
    "frontier projection_chain=29/29",
    "chain_split=",
    "row_frontier=29/29",
    "dense_projection_row_chain=31/31",
    "cached=31",
    "cached=30",
    "dynamic=0/0",
    "schedule_fail=0/0",
    "sync=1",
    "patch_calls=3/3",
    "patch_calls=600/600",
    "patch_changed=600",
    "stencil_hash pp=17558208047327870709/17558208047327870709 tg=14405191909906507341/14405191909906507341",
  ]);
  const substrateLine = output.split("\n").find((line) => line.startsWith("bench substrate gate:")) ?? "";
  requirePattern(substrateLine, "bench substrate gate output", "f16 prompt dispatch/stencil/fallback proof", /f16\/prompt=[^;]+ggml=[^;]+to90=[^;]+ref=[^;]+dispatch=242 commands=242 cached=31 dynamic=0\/0 schedule_fail=0\/0 sync=1 patch_holes=450 patch_calls=3\/3 patch_changed=0 stencil=17558208047327870709\/17558208047327870709 fallback=0/);
  requirePattern(substrateLine, "bench substrate gate output", "f16 decode dispatch/stencil/fallback proof", /f16\/decode=[^;]+ggml=[^;]+to90=[^;]+ref=[^;]+dispatch=212 commands=212 cached=31 dynamic=0\/0 schedule_fail=0\/0 sync=1 patch_holes=450 patch_calls=600\/600 patch_changed=600 stencil=14405191909906507341\/14405191909906507341 fallback=0/);
  requirePattern(substrateLine, "bench substrate gate output", "q8 prompt dispatch/stencil/fallback proof", /q8_0\/prompt=[^;]+ggml=[^;]+to90=[^;]+ref=[^;]+dispatch=242 commands=(?:181|241) cached=30 dynamic=0\/0 schedule_fail=0\/0 sync=1 patch_holes=450 patch_calls=3\/3 patch_changed=0 stencil=17558208047327870709\/17558208047327870709 fallback=0/);
  requirePattern(substrateLine, "bench substrate gate output", "q8 decode dispatch/stencil/fallback proof", /q8_0\/decode=[^;]+ggml=[^;]+to90=[^;]+ref=[^;]+dispatch=212 commands=211 cached=30 dynamic=0\/0 schedule_fail=0\/0 sync=1 patch_holes=450 patch_calls=600\/600 patch_changed=600 stencil=14405191909906507341\/14405191909906507341 fallback=0/);
  requirePercentAtLeast(substrateLine, "bench substrate gate output", "ggml-relative substrate evidence", "f16/prompt", 32);
  requirePercentAtLeast(substrateLine, "bench substrate gate output", "ggml-relative substrate evidence", "f16/decode", 31.0);
  requirePattern(substrateLine, "bench substrate gate output", "frontier weakest command-pressure proof", /frontier weakest=q8_0\/prompt ggml=[0-9.]+% to90=[0-9.]+x dispatch=242 commands=(?:241 top=row_chain:61,projection_chain:60,[^;]+ pressure=151\/241 62\.7% target=projection_chain:60 chain_shape=[^;]+ next=semantic_sublayer_or_quantized_projection_chain rejected=projection_row_chain_default_off_needs_model_speedup sidecars=qmatmul_elementwise:60|181 top=projection_row_chain:120,[^;]+ pressure=180\/181 99\.4% target=projection_row_chain:120 chain_shape=[^;]+ next=semantic_sublayer_or_two_phase_tile_parallel_row_chain rejected=default_semantic_row_chain_needs_throughput_kernel sidecars=projection_row_chain:60) q8_decode_sidecars=qmatvec_elementwise:60/);
  requirePercentAtLeast(substrateLine, "bench substrate gate output", "ggml-relative substrate evidence", "q8_0/prompt", 27);
  requirePercentAtLeast(substrateLine, "bench substrate gate output", "ggml-relative substrate evidence", "q8_0/decode", 32);
  requireIncludes(output, "bench substrate gate output", "full-run ggml artifact context", [
    "pass full-run evidence",
    "parity miss, parity not required",
    "required_pass=True",
  ]);
  requireIncludes(output, "bench substrate gate output", "checked baseline comparison", [
    "bench baseline delta:",
    "bench baseline gate: pass",
    "baseline=m5pro-p128-g200-r3",
    "floor=100.0%",
    "dispatch 242/242 fallback 0/0",
    "dispatch 212/212 fallback 0/0",
  ]);
  const baselineLine = output.split("\n").find((line) => line.startsWith("bench baseline delta:")) ?? "";
  requirePercentAtLeast(baselineLine, "bench substrate gate output", "baseline speedup evidence", "F16 pp", 100);
  requirePercentAtLeast(baselineLine, "bench substrate gate output", "baseline speedup evidence", "F16 tg", 100);
  requirePercentAtLeast(baselineLine, "bench substrate gate output", "baseline speedup evidence", "Q8 pp", 100);
  requirePercentAtLeast(baselineLine, "bench substrate gate output", "baseline speedup evidence", "Q8 tg", 100);
  requireIncludes(output, "bench substrate gate output", "checked local trend regression guard", [
    "bench trend:",
    "full p128/g200/r3 runs",
    "bench trend gate: pass",
    "F16 pp=",
    "floor=80.0%",
    "F16 tg=",
    "floor=90.0%",
    "Q8 pp=",
    "Q8 tg=",
  ]);
  const trendGateLine = output.split("\n").find((line) => line.startsWith("bench trend gate:")) ?? "";
  requirePercentAtLeast(trendGateLine, "bench substrate gate output", "trend regression evidence", "F16 pp", 80);
  requirePercentAtLeast(trendGateLine, "bench substrate gate output", "trend regression evidence", "F16 tg", 90);
  requirePercentAtLeast(trendGateLine, "bench substrate gate output", "trend regression evidence", "Q8 pp", 80);
  requirePercentAtLeast(trendGateLine, "bench substrate gate output", "trend regression evidence", "Q8 tg", 90);
  notes.push(output.trim().split("\n").at(-1));
}

