function checkDocs() {
  const readme = read("README.md");
  requireIncludes(readme, "README.md", "goal evidence command", [
    "npm run check:goal-scorecard",
    "npm run bench:pytorch",
    "upstream Python PyTorch",
    "Program/Session substrate",
    "zgml frontend surface",
    "goal progress: Program/Session substrate=93% floor=65%; zgml frontend surface=100% floor=60%",
    "manual `backward`/`step` loops",
    "optimizer parameter groups",
    "snapshots",
    "compile-time shape safety",
    "`@ts-expect-error` cases",
    "class Classifier extends nn.Module<readonly [2], readonly [2]>",
    "new nn.CrossEntropyLoss({ classes: 2 })",
    "classifier.eval()",
    "train.evaluate(loader",
    "train.predictClassifier(classifier, loader)",
    "classifier.compile({ inputShape: [2] as const })",
    "program.bindModule(classifier)",
    "session.requireHotStepParams(hotParams)",
    "session.hotPathPlan(hotParams)",
    "session.executeInto(output, { input })",
    "const classes = train.predictClasses(logits, { classes: 2 })",
    "manual-loop smokes prove explicit",
    "The public root exports `Tensor`, tensor factories, `nn`, `F`, `data`, `loss`,",
    "`optim`, `train`, `checkpoint`, model-source helpers, and explicit",
    "`Program`/`Session` handles from the TS-authored product surface.",
    "LLM users go through model-source helpers such as `probeModel` / `loadModel`,",
  ]);
  const staleReadmeSurface = [
    "`ComputeGraph`",
    "`train`, and `llm`",
    "`zgml.llm`",
    ".addBias(",
    "`fromSlice`",
  ].filter((needle) => readme.includes(needle));
  if (staleReadmeSurface.length !== 0) {
    errors.push(`README.md must not advertise stale public surface lanes: ${staleReadmeSurface.join(", ")}`);
  }

  const plan = read("docs/executable-stencil-runtime-plan.md");
  requireIncludes(plan, "docs/executable-stencil-runtime-plan.md", "current goal progress accounting", [
    "Current checked progress:",
    "Program/Session performance substrate: ~93%",
    "That optional gate now also runs the native WebGPU LLaMA execution proofs for",
    "runtime quantized-weight rebinding, resource-bound decode/prefill handoff,",
    "long-prompt prefill, GQA long-prompt prefill, and a realistic head-width",
    "LayerNorm/RMSNorm descriptors can carry post-affine activations",
    "Full-model F16 SmolLM FFN blocks now",
    "form dense projection-pair commands for `matmul -> silu -> matmul -> mul`",
    "prompt/decode command pressure `242/212`, `30` dense FFN pair commands",
    "A batched `RMSNorm+GELU -> Linear`",
    "sign-style `neg -> abs -> step` chains",
    "Common classifier/token-head `LogSoftmax` tails now",
    "native row op on reference CPU, Metal, and WGPU",
    "capability-disabled test still proves the composite fallback",
    "direct backend reduce-min command on reference CPU, Metal, and WGPU",
    "batched rank-3 last-axis reductions",
    "Compile-capable lazy graphs can now lower through the host adapter into a",
    "native Program with preserved KernelPlan evidence.",
    "zgml frontend replacement feel: ~100%",
    "native Program lowering for `argmax(dim)` and `argmin(dim)`",
    "rank-1/rank-2/rank-3 PyTorch-style",
    "rank-1/rank-2/rank-3 `repeat`/`tile`",
    "rank-3 `reshape`/`flatten`/`squeeze`/`unsqueeze`, rank-3 `broadcastTo`/`expand`,",
    "and rank-3 `narrow`/`select`/`slice`",
    "rank-3 `transpose` plus single-swap and cycle `permute`",
    "rank-3 last-axis `sum`/`mean`/`prod`/`max`/`min`/`argmax`/`argmin` Program lowering",
    "Exploratory focused lanes still track softer micro-workloads",
    "closes the previous",
    "`log_softmax_classifier_batched` softness with a direct CPU",
    "PyTorch comparison output now also prints `ratio_range` and `ratio_median`",
    "ratio_median=linear_batched:0.73x,log_softmax_classifier_batched:0.82x",
    "bench:ggml:parity:run          # rerun hard ggml parity; bench script rebuilds ReleaseFast by default",
    "BENCH_BUILD_ZGML=0",
    "exact-shape",
    "`M=128,N=32,K=64` unrolled direct-linear kernel was tested and rejected",
    "hot_execute_into` around `0.0032ms` instead of the",
    "one-off K-loop unroll",
    "direct CPU `Linear -> LogSoftmax` classifier",
    "Program plan still reports `linear|log-softmax`",
    "post-change three-attempt microscope",
    "found a passing attempt at `3.97x`",
    "native small-direct kernel that uses 16-wide column",
    "This was rechecked against the BLAS-backed direct `Linear -> LogSoftmax`",
    "in-place row `LogSoftmax` still regressed the focused module hot path to about",
    "uses a general vectorized row log-softmax loop",
    "ratio_median=0.83x",
    "best attempts above parity",
    "do not accumulate one-off row-tail special cases",
    "benchmark binaries with `-Doptimize=ReleaseFast`",
    "BENCH_FRONTIER_FILTER=<label-substring>",
    "BENCH_FRONTIER_FILTER=qrow",
    "BENCH_FRONTIER_FILTER=\"qrow region\"",
    "same anchored\nregion-command shape",
    "projection_row_chain_candidate=ready",
    "single_throughput=off",
    "command fusion holds at `0.98x` to `1.02x`",
    "single-dispatch candidate",
    "around `0.19x` to `0.21x`",
    "`two_phase_count`/`two_phase_selected`",
    "`two_phase_count=60`, `two_phase_selected=yes`",
    "landed at `0.86x` versus default",
    "the simpler command candidate landed at `1.02x`",
    "not blindly promoting the shallow two-kernel variant",
    "`lazyGraph.compile()` and compatibility `torch.compile.compile(lazyGraph)`",
    "The remaining substrate",
    "June 22, 2026 full required-GPU browser smoke",
    "74 LLaMA profile labels, 253 backend dispatches",
    "127/127/0/0/0",
    "45 syncs, and zero",
    "fallback ops in about 27.5 minutes",
    "required-GPU browser runner's full",
    "selection-read summary fields",
    "the goal scorecard now attempts a focused",
    "required-GPU browser LLaMA run for `gguf-smollm3-nope-gqa-pipeline`",
    "zig build ffi-wasm-browser-gpu-focused-smoke",
    "mode=gpu-buffer",
    "tiled quantized row-chain",
    "remaining frontend jump is native lowering and breadth,",
    "compile hooks exist.",
  ]);
  if (plan.includes("remaining\nknown miss is the RMSNorm -> SiLU FFN lane") || plan.includes("remaining known miss is the RMSNorm -> SiLU FFN lane")) {
    errors.push("docs/executable-stencil-runtime-plan.md must not describe the old RMSNorm -> SiLU FFN PyTorch lane as a current known miss");
  }
}

runScorecardCheck("static scripts", checkScripts);
runScorecardCheck("substrate evidence", checkSubstrateEvidence);
runScorecardCheck("frontier evidence", checkFrontierEvidence);
runScorecardCheck("q8 prompt candidate evidence", checkQ8PromptCandidateEvidence);
runScorecardCheck("module Program bench evidence", checkModuleProgramBenchEvidence);
runScorecardCheck("portable Wasm runtime evidence", checkPortableWasmRuntimeEvidence);
runScorecardCheck("native WebGPU runtime evidence", checkNativeWgpuRuntimeEvidence);
runScorecardCheck("zgml frontend surface", checkZgmlFrontendSurface);
runScorecardCheck("docs", checkDocs);

if (errors.length > 0) {
  console.error(`zgml goal scorecard failed with ${errors.length} issue(s):`);
  for (const error of errors) console.error(`- ${error}`);
  process.exit(1);
}

console.log("zgml goal scorecard ok");
console.log(
  `goal progress: Program/Session substrate=${goalProgress.substratePct}% floor=${goalProgress.substrateFloorPct}%; ` +
    `zgml frontend surface=${goalProgress.frontendPct}% floor=${goalProgress.frontendFloorPct}%`,
);
for (const note of notes) console.log(note);
